INSERT INTO rco16_platform_gate SELECT IF((SELECT COUNT(*) FROM t_role WHERE role_id = 900000000000000510 AND role_code = 'PLATFORM_ADMIN' AND tenant_scope = 'PLATFORM' AND tenant_id IS NULL AND scope_key = 'PLATFORM' AND status = 'ACTIVE' AND system_role = 1 AND version < 2147483647) = 1, 'exact existing administrator role', NULL);
