INSERT INTO rco16_platform_gate SELECT IF((SELECT COUNT(*) FROM t_gateway_route WHERE route_id = 900000000000001024 AND route_code = 'operations-risk-rule-authoring-context' AND channel = 'OPERATIONS' AND http_method = 'GET' AND downstream_path_template = '/decision-rule-sets/v1/authoring-context/{pointCode}' AND target_id = 900000000000000001 AND security_profile_code = 'OPERATIONS_JWT' AND authorization_mode = 'HUMAN_PERMISSION') = 1, 'exact existing Risk BFF route identity', NULL);
