th_template = '/api/operations/decision-dictionaries/v1/subject-tags') OR (http_method = 'PUT' AND external_path_template = '/api/operations/decision-dictionaries/v1/subject-tags/{tagCode}') OR (http_method = 'POST' AND external_path_template = '/api/operations/decision-dictionaries/v1/subject-tags/{tagCode}/status') OR (http_method = 'GET' AND external_path_template = '/api/operations/decision-dictionaries/v1/subject-tags/{tagCode}/references')))), 'route codes and literal method paths absent', NULL);
