-- RCO-16 阶段 3 评审稿，未执行；registration.json 是逐项注册清单。
-- 仅人工连接批准环境的 mor_platform；先备份受影响配置并暂停控制面写入。
-- mysql --batch，禁止 --force；新 Route/Resource 均 DISABLED，本文件不发布 Snapshot 或启用路由。
-- 182 条插入：6 Permission、6 RolePermission、10 Resource、14 Route、40 Header、22 Query、84 Guard。
-- 另对 PLATFORM_ADMIN 的 Role.version 做一次 CAS +1；不授予只读角色写权限。
SET @rco16_platform_saved_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = 'STRICT_ALL_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION,NO_ZERO_DATE,NO_ZERO_IN_DATE';
CREATE TEMPORARY TABLE rco16_platform_gate (checkpoint VARCHAR(100) NOT NULL);
START TRANSACTION;
SELECT version INTO @rco16_admin_role_version FROM t_role WHERE role_id = 900000000000000510 FOR UPDATE;
-- 模板等价冲突、完整 Catalog 和权限继承仍须在实际环境用既有控制面验证。
SET @rco16_registration_time = UTC_TIMESTAMP(6);
-- 待发布绑定暂不生效；与 Route 开放在同一发布事务中切为 ACTIVE。
UPDATE t_role SET version = version + 1, update_time = @rco16_registration_time WHERE role_id = 900000000000000510 AND version = @rco16_admin_role_version AND status = 'ACTIVE';
COMMIT;
DROP TEMPORARY TABLE rco16_platform_gate;
SET SESSION sql_mode = @rco16_platform_saved_sql_mode;
-- 本次撤销主体类型查询及字典幂等 Header 注册，不影响既有规则集命令路由。
-- 撤销的首稿注册 ID 留空，不重新分配；首稿 SQL 从未应用，无数据库删除语句。
-- 研发阶段同步服务单一初始化 DML；新环境初始化与本增量互斥，不能重复执行。
